DROP INDEX jobs_fetch_problem_recovery;
CREATE INDEX jobs_fetch_problem_recovery ON jobs(id) WHERE kind='fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch');
DROP INDEX reader_fetch_problem_recovery;
CREATE INDEX reader_fetch_problem_recovery ON reader_problems(created,id COLLATE "C") WHERE finished IS NULL AND identity LIKE 'job:%' AND body::jsonb->>'operation' IN ('producer:fetch','producer:status') AND body::jsonb->>'code' IS NOT NULL AND body::jsonb->>'code'<>'' AND body::jsonb->>'code' NOT LIKE 'source-%' AND body::jsonb->>'code' NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-fetch') AND coalesce(body::jsonb->>'fetch_job_identity',identity) LIKE 'job:%:fetch:%';
DROP INDEX jobs_unmanaged_problems;
CREATE INDEX jobs_unmanaged_problems ON jobs(kind,item) WHERE kind IS DISTINCT FROM 'read' AND kind IS DISTINCT FROM 'discover' AND problem_code IS DISTINCT FROM 'processor-config' AND NOT (kind IN ('delete','feed-delete') AND coalesce(nullif(problem_code,''),'work-'||kind) IN ('delete','feed-delete','work-delete','work-feed-delete')) AND NOT (kind IS NOT DISTINCT FROM 'fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch')) AND (problem_code IS NOT NULL OR error IS NOT NULL) AND NOT (kind IS NOT DISTINCT FROM 'download_media' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-download_media')) AND NOT ((kind IS NOT DISTINCT FROM 'filter' OR kind IS NOT DISTINCT FROM 'theses') AND item IS NOT NULL AND item<>'' AND (((problem_code='' OR (problem_code IS NULL AND error IS NOT NULL))) OR (problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch'))));
CREATE INDEX jobs_fetch_feed_wait ON jobs(feed_id,item) WHERE kind='fetch' AND status IN ('pending','running') AND problem_code IN ('','work-fetch');
CREATE INDEX reader_fetch_status_identity ON reader_problems ((body::jsonb->>'status_job_identity')) WHERE finished IS NULL AND body::jsonb->>'operation'='producer:fetch';
CREATE INDEX reader_fetch_work_legacy_item ON reader_problems ((substring(coalesce(body::jsonb->>'status_job_identity',identity) FROM ':fetch:(.*)$'))) WHERE finished IS NULL AND identity LIKE 'job:%' AND body::jsonb->>'code'='work-fetch' AND body::jsonb->>'operation' IN ('producer:fetch','producer:status');
